// Initialize output with safe defaults
sd_output.mode = SD_OFF;
sd_output.accepted = FALSE32;
sd_output.rejects = 0;
sd_output.cosine = 0.0;
sd_output.innovation_rad = 0.0;
sd_output.reference.x = 0.0;
sd_output.reference.y = 0.0;
sd_output.reference.z = 0.0;

// 1. Handle Disable (OFF state)
if (sd_input.enable == 0) {
    sd_state.mode = SD_OFF;
    sd_state.initialized = 0;
    sd_state.rejects = 0;
    sd_state.reacquire_count = 0;
    sd_state.reference.x = 0.0;
    sd_state.reference.y = 0.0;
    sd_state.reference.z = 0.0;
    sd_output.mode = SD_OFF;
    return;
}

// 2. Check for Fault Conditions (Parameter Validation)
int param_fault = FALSE32;
if (!isfinite(sd_config.alpha) || sd_config.alpha <= 0.0 || sd_config.alpha > 1.0) {
    param_fault = TRUE32;
}
if (!isfinite(sd_config.minimum_cosine) || sd_config.minimum_cosine < -1.0 || sd_config.minimum_cosine > 1.0) {
    param_fault = TRUE32;
}
if (!isfinite(sd_config.reacquire_min_cosine) || sd_config.reacquire_min_cosine < -1.0 || sd_config.reacquire_min_cosine > 1.0) {
    param_fault = TRUE32;
}
if (sd_config.max_rejects < 1 || sd_config.max_rejects > 20) {
    param_fault = TRUE32;
}
if (sd_config.reacquire_confirm < 1 || sd_config.reacquire_confirm > 20) {
    param_fault = TRUE32;
}

// 3. Check for Fault Conditions (Input Vector Validation)
int input_fault = FALSE32;
adcs_vec3_t norm_sample = {0, 0, 0};
if (sd_input.sun_body == NULL) {
    input_fault = TRUE32;
} else if (!adcs_is_finite_vec3(sd_input.sun_body)) {
    input_fault = TRUE32;
} else {
    if (adcs_vec3_normalize(sd_input.sun_body, ADCS_EPS_NORM, &norm_sample) != ADCS_OK) {
        input_fault = TRUE32;
    }
}

// 4. Determine Fault State
// FAULT latches until disable. If currently in FAULT, stay in FAULT.
// If param_fault or input_fault is true, enter FAULT.
if (sd_state.mode == SD_FAULT || param_fault || input_fault) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.accepted = FALSE32;
    // Preserve reference and counters on fault
    sd_output.reference = sd_state.reference;
    sd_output.rejects = sd_state.rejects;
    sd_output.cosine = 0.0;
    sd_output.innovation_rad = 0.0;
    return;
}

// 5. Normal Operation (Modes: TRACK, REJECT, LOST)
// Note: OFF is handled above. FAULT is handled above.

double cosine = adcs_vec3_dot(&norm_sample, &sd_state.reference);
// Clamp for numerical stability
if (cosine > 1.0) cosine = 1.0;
if (cosine < -1.0) cosine = -1.0;

sd_output.cosine = cosine;
sd_output.innovation_rad = acos(cosine);
sd_output.rejects = sd_state.rejects;
sd_output.reference = sd_state.reference; // Default preserve

if (!sd_state.initialized) {
    // First valid sample initializes reference
    sd_state.reference = norm_sample;
    sd_state.mode = SD_TRACK;
    sd_state.rejects = 0;
    sd_state.reacquire_count = 0;
    sd_state.initialized = 1;

    sd_output.mode = SD_TRACK;
    sd_output.accepted = TRUE32;
    sd_output.reference = sd_state.reference;
    sd_output.rejects = 0;
    return;
}

if (sd_state.mode == SD_TRACK || sd_state.mode == SD_REJECT) {
    if (cosine >= sd_config.minimum_cosine) {
        // Accept: Blend reference
        adcs_vec3_t blended = adcs_vec3_add(
            &adcs_vec3_scale(&sd_state.reference, 1.0 - sd_config.alpha),
            &adcs_vec3_scale(&norm_sample, sd_config.alpha)
        );
        sd_state.reference = blended;
        sd_state.rejects = 0;
        sd_state.mode = SD_TRACK;

        sd_output.mode = SD_TRACK;
        sd_output.accepted = TRUE32;
        sd_output.reference = sd_state.reference;
        sd_output.rejects = 0;
    } else {
        // Reject
        sd_state.rejects++;
        if (sd_state.rejects >= sd_config.max_rejects) {
            sd_state.mode = SD_LOST;
            sd_output.mode = SD_LOST;
        } else {
            sd_state.mode = SD_REJECT;
            sd_output.mode = SD_REJECT;
        }
        sd_output.accepted = FALSE32;
        sd_output.reference = sd_state.reference; // Preserve
        sd_output.rejects = sd_state.rejects;
    }
} else if (sd_state.mode == SD_LOST) {
    if (cosine >= sd_config.reacquire_min_cosine) {
        sd_state.reacquire_count++;
        if (sd_state.reacquire_count >= sd_config.reacquire_confirm) {
            // Reacquisition confirmed: Blend and return to TRACK
            adcs_vec3_t blended = adcs_vec3_add(
                &adcs_vec3_scale(&sd_state.reference, 1.0 - sd_config.alpha),
                &adcs_vec3_scale(&norm_sample, sd_config.alpha)
            );
            sd_state.reference = blended;
            sd_state.rejects = 0;
            sd_state.reacquire_count = 0;
            sd_state.mode = SD_TRACK;

            sd_output.mode = SD_TRACK;
            sd_output.accepted = TRUE32;
            sd_output.reference = sd_state.reference;
            sd_output.rejects = 0;
        } else {
            // Still acquiring
            sd_output.mode = SD_LOST;
            sd_output.accepted = FALSE32;
            sd_output.reference = sd_state.reference; // Frozen
            sd_output.rejects = sd_state.rejects;
        }
    } else {
        // Below threshold in LOST
        sd_state.reacquire_count = 0;
        sd_output.mode = SD_LOST;
        sd_output.accepted = FALSE32;
        sd_output.reference = sd_state.reference; // Frozen
        sd_output.rejects = sd_state.rejects;
    }
}

