sd_output.innovation_rad = 0.0;
sd_output.reference.x = 0.0;
sd_output.reference.y = 0.0;
sd_output.reference.z = 0.0;

// 1. Check Enable and Pointer Validity
if (sd_input.enable != TRUE32 || sd_input.sun_body == NULL) {
    if (sd_input.enable != TRUE32) {
        // Disable: Clear state
        sd_state.mode = SD_OFF;
        sd_state.initialized = FALSE32;
        sd_state.rejects = 0;
        sd_state.reacquire_count = 0;
        sd_state.reference.x = 0.0;
        sd_state.reference.y = 0.0;
        sd_state.reference.z = 0.0;

        sd_output.mode = SD_OFF;
        sd_output.accepted = FALSE32;
        sd_output.rejects = 0;
        sd_output.cosine = 0.0;
        sd_output.innovation_rad = 0.0;
        sd_output.reference = sd_state.reference;
        return;
    } else {
        // Enabled but NULL input -> FAULT
        sd_state.mode = SD_FAULT;
        sd_output.mode = SD_FAULT;
        sd_output.reference = sd_state.reference;
        return;
    }
}

// 2. Validate Configuration Parameters
if (sd_config.alpha <= 0.0 || sd_config.alpha > 1.0) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}
if (sd_config.minimum_cosine < -1.0 || sd_config.minimum_cosine > 1.0) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}
if (sd_config.reacquire_min_cosine < -1.0 || sd_config.reacquire_min_cosine > 1.0) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}
if (sd_config.max_rejects < 1 || sd_config.max_rejects > 20) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}
if (sd_config.reacquire_confirm < 1 || sd_config.reacquire_confirm > 20) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}

// 3. Validate Input Vector
if (!adcs_is_finite_vec3(sd_input.sun_body)) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}

adcs_vec3_t normalized_sample;
if (adcs_vec3_normalize(sd_input.sun_body, ADCS_EPS_NORM, &normalized_sample) != ADCS_OK) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.reference = sd_state.reference;
    return;
}

// 4. Handle FAULT State Persistence
if (sd_state.mode == SD_FAULT) {
    sd_output.mode = SD_FAULT;
    sd_output.accepted = FALSE32;
    sd_output.rejects = sd_state.rejects;
    sd_output.cosine = 0.0;
    sd_output.innovation_rad = 0.0;
    sd_output.reference = sd_state.reference;
    return;
}

// 5. Calculate Cosine and Innovation
double cosine = adcs_vec3_dot(&normalized_sample, &sd_state.reference);
if (cosine > 1.0) cosine = 1.0;
if (cosine < -1.0) cosine = -1.0;

double innovation_rad = acos(cosine);

sd_output.cosine = cosine;
sd_output.innovation_rad = innovation_rad;
sd_output.reference = sd_state.reference;

// 6. State Machine Logic
switch (sd_state.mode) {
    case SD_OFF:
        // First valid sample initializes reference
        sd_state.mode = SD_TRACK;
        sd_state.initialized = TRUE32;
        sd_state.rejects = 0;
        sd_state.reacquire_count = 0;
        sd_state.reference = normalized_sample;

        sd_output.mode = SD_TRACK;
        sd_output.accepted = TRUE32;
        sd_output.rejects = 0;
        sd_output.reference = sd_state.reference;
        break;

    case SD_TRACK:
    case SD_REJECT:
        if (cosine >= sd_config.minimum_cosine) {
            // Accept
            adcs_vec3_t blended = adcs_vec3_scale(&sd_state.reference, 1.0 - sd_config.alpha);
            adcs_vec3_t scaled_sample = adcs_vec3_scale(&normalized_sample, sd_config.alpha);
            adcs_vec3_t raw_blend = adcs_vec3_add(&blended, &scaled_sample);

            if (adcs_vec3_normalize(&raw_blend, ADCS_EPS_NORM, &sd_state.reference) != ADCS_OK) {
                 sd_state.mode = SD_FAULT;
                 sd_output.mode = SD_FAULT;
                 sd_output.reference = sd_state.reference;
                 return;
            }

            sd_state.rejects = 0;
            sd_state.reacquire_count = 0;
            sd_state.mode = SD_TRACK;

            sd_output.mode = SD_TRACK;
            sd_output.accepted = TRUE32;
            sd_output.rejects = 0;
            sd_output.reference = sd_state.reference;
        } else {
            // Reject
            sd_state.rejects++;
            if (sd_state.rejects >= sd_config.max_rejects) {
                sd_state.mode = SD_LOST;
                sd_state.reacquire_count = 0;
            } else {
                sd_state.mode = SD_REJECT;
            }

            sd_output.mode = sd_state.mode;
            sd_output.accepted = FALSE32;
            sd_output.rejects = sd_state.rejects;
            sd_output.reference = sd_state.reference;
